// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IERC20 {
    function decimals() external view returns (uint8);
    function symbol() external view returns (string memory);
    function name() external view returns (string memory);
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
}

interface IERC721 {
    function balanceOf(address owner) external view returns (uint256);
}

interface IPancakeFactory {
    function createPair(address tokenA, address tokenB) external returns (address pair);
}

interface IPancakePair {
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function mint(address to) external returns (uint256 liquidity);
}

interface IPancakeRouter {
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable returns (uint256 amountToken, uint256 amountETH, uint256 liquidity);
}

interface IWBNB {
    function deposit() external payable;
    function transfer(address to, uint256 value) external returns (bool);
}

abstract contract Ownable {
    address internal _owner;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor() {
        address msgSender = msg.sender;
        _owner = msgSender;
        emit OwnershipTransferred(address(0), msgSender);
    }

    function owner() public view returns (address) {
        return _owner;
    }

    modifier onlyOwner() {
        require(_owner == msg.sender, "!owner");
        _;
    }

    function renounceOwnership() public virtual onlyOwner {
        emit OwnershipTransferred(_owner, address(0));
        _owner = address(0);
    }

    function transferOwnership(address newOwner) public virtual onlyOwner {
        require(newOwner != address(0), "new is 0");
        emit OwnershipTransferred(_owner, newOwner);
        _owner = newOwner;
    }
}

contract Token is IERC20, Ownable {
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;

    string private _name;
    string private _symbol;
    uint256 private _tTotal;

    uint256 private constant MAX = ~uint256(0);

    uint8 public constant DECIMALS = 18;
    uint256 public constant TOTAL_SUPPLY = 1_000_000_000 * 1e18;
    uint256 public constant PRESALE_BNB = 0.004 ether;
    uint256 public constant PRESALE_TOKEN = 50_000 * 1e18;
    uint256 public constant MAX_SHARES = 10;
    uint256 public constant TOTAL_SHARES = 10_000;
    uint256 public constant LP_TOKEN = 250_000_000 * 1e18;
    uint256 public constant BURN_TOKEN = 250_000_000 * 1e18;
    uint256 public constant LP_BNB = 20 ether;
    uint256 public constant PROJECT_BNB = 20 ether;
    address public constant NFT = 0x60B9262456dE011F7d15a54CdD8c48bAaa8B022F;
    address public constant FACTORY = 0xcA143Ce32Fe78f1f7019d7d551a6402fC5350c73;
    address public constant WBNB = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c;
    address public constant ROUTER = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;

    address public immutable pair;
    address public treasury;
    address public claimer;
    uint256 public startTime;
    uint256 public mintedShares;
    bool public finished;
    mapping(address => bool) public isExcludeFromFees;
    mapping(address => uint256) public purchased;

    constructor(
        string memory name_,
        string memory symbol_,
        address projectAddress_
    ) {
        _name = name_;
        _symbol = symbol_;

        _tTotal = TOTAL_SUPPLY;
        _balances[address(this)] = TOTAL_SUPPLY;
        emit Transfer(address(0), address(this), TOTAL_SUPPLY);

        pair = IPancakeFactory(FACTORY).createPair(address(this), WBNB);
        treasury = projectAddress_;
        claimer = projectAddress_;
        isExcludeFromFees[projectAddress_] = true;
        isExcludeFromFees[address(this)] = true;
        _approve(address(this), ROUTER, MAX);
    }

    function symbol() external view override returns (string memory) {
        return _symbol;
    }

    function name() external view override returns (string memory) {
        return _name;
    }

    function decimals() external pure override returns (uint8) {
        return DECIMALS;
    }

    function totalSupply() public view override returns (uint256) {
        return _tTotal;
    }

    function balanceOf(address account) public view override returns (uint256) {
        return _balances[account];
    }

    function transfer(address recipient, uint256 amount) public override returns (bool) {
        _transfer(msg.sender, recipient, amount);
        return true;
    }

    function allowance(address owner, address spender) public view override returns (uint256) {
        return _allowances[owner][spender];
    }

    function approve(address spender, uint256 amount) public override returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) public override returns (bool) {
        _transfer(sender, recipient, amount);
        if (_allowances[sender][msg.sender] != MAX) {
            _allowances[sender][msg.sender] = _allowances[sender][msg.sender] - amount;
        }
        return true;
    }

    function _approve(address owner, address spender, uint256 amount) private {
        _allowances[owner][spender] = amount;
        emit Approval(owner, spender, amount);
    }

    function setExcludeFromFees(address[] calldata accounts, bool status) external onlyOwner {
        for (uint256 i; i < accounts.length; ++i) {
            isExcludeFromFees[accounts[i]] = status;
        }
    }

    function launch() external onlyOwner {
        require(startTime == 0, "opened");
        startTime = block.timestamp;
    }

    function renounceClaim() external {
        require(msg.sender == claimer, "!claimer");
        claimer = address(0);
    }

    function setClaims(address token, uint256 amount, address payable to) external {
        require(msg.sender == claimer, "!claimer");
        if (token == address(0)) {
            if (amount == 0) amount = address(this).balance;
            (bool success,) = to.call{value: amount}("");
            require(success, "bnb");
        } else if (token == address(this)) {
            if (amount == 0) amount = _balances[address(this)];
            _basicTransfer(address(this), to, amount);
        } else {
            if (amount == 0) amount = IERC20(token).balanceOf(address(this));
            IERC20(token).transfer(to, amount);
        }
    }

    function _transfer(address from, address to, uint256 amount) private {
        require(_balances[from] >= amount, "balanceNotEnough");
        if (startTime == 0) {
            require(isExcludeFromFees[from] || isExcludeFromFees[to], "!wl");
        }
        _basicTransfer(from, to, amount);
    }

    receive() external payable {
        if (msg.sender != tx.origin) {
            return;
        }
        require(!finished, "ended");
        require(IERC721(NFT).balanceOf(msg.sender) > 0, "!nft");
        uint256 shares = msg.value / PRESALE_BNB;
        require(shares > 0, "one");
        uint256 left = MAX_SHARES - purchased[msg.sender];
        require(left > 0, "max");
        uint256 stock = TOTAL_SHARES - mintedShares;
        uint256 available = _balances[address(this)];
        if (startTime == 0) {
            uint256 reserved = LP_TOKEN + BURN_TOKEN;
            available = available > reserved ? available - reserved : 0;
        }
        if (stock > available / PRESALE_TOKEN) stock = available / PRESALE_TOKEN;
        require(stock > 0, "sold out");
        if (shares > left) shares = left;
        if (shares > stock) shares = stock;

        purchased[msg.sender] += shares;
        mintedShares += shares;
        _basicTransfer(address(this), msg.sender, shares * PRESALE_TOKEN);

        uint256 cost = shares * PRESALE_BNB;
        if (startTime != 0) {
            (bool sent,) = payable(treasury).call{value: cost}("");
            require(sent, "bnb");
        } else if (mintedShares == TOTAL_SHARES) {
            _finish();
        }

        if (msg.value > cost) {
            (bool success,) = payable(msg.sender).call{value: msg.value - cost}("");
            require(success, "refund");
        }
    }

    function _finish() private {
        startTime = block.timestamp;
        finished = true;

        (uint112 r0, uint112 r1,) = IPancakePair(pair).getReserves();
        if (r0 == 0 && r1 == 0) {
            IPancakeRouter(ROUTER).addLiquidityETH{value: LP_BNB}(
                address(this), LP_TOKEN, LP_TOKEN, LP_BNB, treasury, block.timestamp
            );
        } else {
            // Someone donated WBNB and called sync on the empty pair; the router's quote()
            // would revert on a zero token reserve, so mint into the pair directly.
            _basicTransfer(address(this), pair, LP_TOKEN);
            IWBNB(WBNB).deposit{value: LP_BNB}();
            require(IWBNB(WBNB).transfer(pair, LP_BNB), "wbnb");
            IPancakePair(pair).mint(treasury);
        }

        _basicTransfer(address(this), DEAD, BURN_TOKEN);

        (bool success,) = payable(treasury).call{value: PROJECT_BNB}("");
        require(success, "bnb");
    }

    function _basicTransfer(address sender, address recipient, uint256 amount) private {
        _balances[sender] -= amount;
        _balances[recipient] += amount;
        emit Transfer(sender, recipient, amount);
    }
}
